def count_heads(config):
    return config.count('H')

def flip_kth(config, k):
    # k is 1-indexed
    config_list = list(config)
    if 1 <= k <= len(config_list):
        # Flip the k-th coin (index k-1)
        current_char = config_list[k-1]
        config_list[k-1] = 'T' if current_char == 'H' else 'H'
        return "".join(config_list)
    return config

# Memoization dictionary for ell(C)
ell_cache = {}

def ell(config, N):
    if config in ell_cache:
        return ell_cache[config]

    k = count_heads(config)

    if k == 0:
        return 0

    # Perform the move
    next_config = flip_kth(config, k)

    # Recursive call
    result = 1 + ell(next_config, N)

    ell_cache[config] = result
    return result

def calculate_expected_ell(N):
    global ell_cache
    ell_cache = {}

    configs = ["".join(p) for p in itertools.product(['H', 'T'], repeat=N)]

    total_ell = 0
    for config in configs:
        total_ell += ell(config, N)

    return total_ell / (2**N)

import itertools

# Calculate E_1, E_2, E_3, E_4
